import { useState, useEffect } from 'react';
import { Outlet, useNavigate, Link, Routes, Route } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

// Import student pages
import StudentHome from './StudentHome';
import Exams from './Exams';
import Marks from './Marks';

const styles = {
  container: {
    background: '#f6f7fa',
    minHeight: '100vh'
  },
  sidebar: {
    background: '#0e1a35',
    height: '100vh',
    position: 'fixed',
    width: '250px',
    zIndex: 1000
  },
  logo: {
    textAlign: 'center',
    padding: '16px 0'
  },
  logoImg: {
    maxWidth: '180px',
    width: '100%'
  },
  navItem: {
    borderBottom: '1px solid #0d172e',
    borderTop: '1px solid #0d172e',
    color: '#ffffff',
    display: 'block',
    fontSize: '17px',
    fontWeight: '500',
    padding: '28px 20px',
    textDecoration: 'none'
  },
  navItemActive: {
    background: '#122143',
    borderLeft: '5px solid #5584ff',
    paddingLeft: '15px'
  },
  navIcon: {
    marginRight: '15px',
    color: '#5584ff'
  },
  mainContent: {
    marginLeft: '250px',
    padding: '20px'
  },
  mobileHeader: {
    background: '#0e1a35',
    color: 'white',
    padding: '15px',
    display: 'none'
  },
  hamburger: {
    background: 'none',
    border: 'none',
    color: 'white',
    fontSize: '24px',
    cursor: 'pointer'
  },
  header: {
    background: '#ffffff',
    boxShadow: '0 1px 12px rgba(0,0,0,0.04)',
    padding: '15px',
    marginBottom: '20px'
  }
};

export default function StudentDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('home');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  // Set active tab based on URL
  useEffect(() => {
    const path = window.location.pathname;
    if (path === '/dashboard') setActiveTab('home');
    else if (path === '/dashboard/exams') setActiveTab('exams');
    else if (path === '/dashboard/marks') setActiveTab('marks');
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
  };

  // Handle responsive behavior
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) {
        setSidebarOpen(false);
      } else {
        setSidebarOpen(true);
      }
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  return (
    <div style={styles.container}>
      {/* Mobile Header */}
      <div 
        style={{ 
          ...styles.mobileHeader, 
          display: window.innerWidth < 768 ? 'flex' : 'none',
          justifyContent: 'space-between',
          alignItems: 'center'
        }}
      >
        <button onClick={toggleSidebar} style={styles.hamburger}>
          ☰
        </button>
        <h4>Student Dashboard</h4>
        <div></div>
      </div>

      {/* Sidebar */}
      <div 
        style={{ 
          ...styles.sidebar,
          display: window.innerWidth < 768 ? (sidebarOpen ? 'block' : 'none') : 'block'
        }}
      >
        <div style={styles.logo}>
          <img 
            src="logo.png" 
            alt="Quiz Logo" 
            style={styles.logoImg}
          />
        </div>
        <div className="navi">
          <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
            {[
              { id: 'home', label: 'Home', icon: 'fa-home', path: '/dashboard' },
              { id: 'exams', label: 'Exams', icon: 'fa-book', path: '/dashboard/exams' },
              { id: 'marks', label: 'Marks', icon: 'fa-chart-bar', path: '/dashboard/marks' }
            ].map(item => (
              <li key={item.id}>
                <Link 
                  to={item.path}
                  onClick={() => {
                    setActiveTab(item.id);
                    if (window.innerWidth < 768) setSidebarOpen(false);
                  }}
                  style={{
                    ...styles.navItem,
                    ...(activeTab === item.id ? styles.navItemActive : {})
                  }}
                >
                  <i className={`fa ${item.icon}`} style={styles.navIcon}></i>
                  <span>{item.label}</span>
                </Link>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Main Content */}
      <div 
        style={{ 
          ...styles.mainContent,
          marginLeft: window.innerWidth < 768 ? '0' : '250px'
        }}
      >
        <header style={styles.header}>
          <div className="d-flex justify-content-between align-items-center">
            <h2>
              {activeTab === 'home' ? 'Student Dashboard' : 
               activeTab === 'exams' ? 'Available Exams' :
               activeTab === 'marks' ? 'Your Marks' : 'Student Dashboard'}
            </h2>
            <button 
              onClick={handleLogout}
              className="btn btn-danger btn-sm"
            >
              Logout
            </button>
          </div>
        </header>

        {/* Nested Routes */}
        <Routes>
          <Route index element={<StudentHome />} />
          <Route path="exams" element={<Exams />} />
          <Route path="marks" element={<Marks />} />
        </Routes>
      </div>
    </div>
  );
}
